let lang='ar', chapter='tour', index=0, current, buffers={}, queue={q:'',status:'all',product:'all',assignment:'all',sort:'date-desc',page:1}, opener=null;
const $=q=>document.querySelector(q), t=(ar,en)=>lang==='ar'?ar:en, txt=a=>t(...a), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), ltr=v=>`<bdi dir="ltr">${esc(v)}</bdi>`, entered=v=>`<bdi dir="auto">${esc(v)}</bdi>`;
const btn=(text,action,extra='',kind='')=>`<button type="button" data-action="${action}" ${extra} class="${kind}">${text}</button>`;
const canonicalNumber=n=>Number(String(n).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[,٬]/g,''));
const money=n=>Number.isFinite(canonicalNumber(n))?ltr(canonicalNumber(n).toLocaleString('en-US'))+' '+t('ر.ي.','YER'):t('قيمة غير مكتملة','Incomplete value');
const date=d=>d?new Intl.DateTimeFormat(lang==='ar'?'ar-YE-u-ca-gregory-nu-latn':'en-GB-u-ca-gregory-nu-latn',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')):t('لم يُرسل بعد','Not submitted');
const product=p=>p==='equipment'?t('تمويل المعدات','Equipment financing'):t('تمويل المخزون','Inventory financing');
const badge=(key,type='status')=>`<span class="pill ${key}">${txt((type==='status'?statusLabels:type==='doc'?docStates:checkStates)[key])}</span>`;
const def=(k,v)=>`<div class="definition"><dt>${k}</dt><dd>${v}</dd></div>`;
const panel=(title,body,cls='')=>`<section class="panel ${cls}"><h2>${title}</h2>${body}</section>`;
const notice=(text,cls='')=>`<div class="notice ${cls}">${text}</div>`;
const jump=(text,c,i,cls='')=>btn(text,'jump',`data-chapter="${c}" data-index="${i}"`,cls);
const original=()=>seeds.find(r=>r.id===current.record.id);
function primaryNext(){const n=sceneCount();return index<n-1?btn(t('تابع: ','Continue: ')+txt(specAt(index+1).label),'next','','primary'):btn(t('العودة إلى بداية الجولة','Restart chapter'),'restart');}
function sceneCount(){return chapter==='tour'?tourRefs.length:chapters.find(c=>c.key===chapter).steps.length;}
function specAt(i){return chapter==='tour'?chapters[tourRefs[i][0]].steps[tourRefs[i][1]]:chapters.find(c=>c.key===chapter).steps[i];}
function field(key,ar,en,value,opts={}){const val=Object.hasOwn(buffers,key)?buffers[key]:value;const invalid=current.spec.error&&(key==='explanation'&&current.spec.error==='explanation'||current.spec.error==='product'&&['amount','term'].includes(key));return `<div class="field ${opts.full?'full':''}"><label for="f-${key}">${t(ar,en)} ${opts.optional?'':`<span aria-hidden="true">*</span>`}</label>${opts.area?`<textarea id="f-${key}" data-field="${key}" dir="auto" ${opts.readonly?'readonly':''} ${invalid?'aria-invalid="true"':''} aria-describedby="hint-${key}">${esc(val)}</textarea>`:`<input id="f-${key}" data-field="${key}" value="${esc(val)}" dir="${opts.numeric?'ltr':'auto'}" ${opts.numeric?'inputmode="numeric"':''} ${opts.readonly?'readonly':''} ${invalid?'aria-invalid="true"':''} aria-describedby="hint-${key}">`}<p id="hint-${key}" class="small ${invalid?'error-text':'muted'}">${invalid?key==='explanation'?t('أدخل وصفاً بين 20 و500 حرف.','Enter a description of 20–500 characters.'):key==='amount'?t('المعدات: من 500,000 إلى 3,000,000 ر.ي.','Equipment: 500,000–3,000,000 YER.'):t('المعدات: 12 أو18 أو24 شهراً.','Equipment: 12, 18 or 24 months.'):opts.hint||t('يحفظ النص كما أُدخل.','Preserves input as entered.')}</p></div>`;}
function financing(r){r={...r,amount:canonicalNumber(r.amount),term:canonicalNumber(r.term)};const rate=r.product==='equipment'?8:5,mark=Math.floor((r.amount*rate+50)/100),total=r.amount+mark,regular=Math.floor(total/r.term),final=total-regular*(r.term-1);return {rate,mark,total,regular,final};}
function summary(r){const f=financing(r);return panel(t('ملخص التمويل','Financing summary'),`<p>${product(r.product)}</p><p class="amount">${money(r.amount)}</p><dl>${def(t('المدة','Term'),ltr(r.term)+' '+t('شهراً','months'))}${def(t('الزيادة التوضيحية','Illustrative markup'),money(f.mark)+' · '+ltr(f.rate+'%'))}${def(t('إجمالي السداد التوضيحي','Illustrated repayment total'),money(f.total))}${def(t('أكبر قسط توضيحي','Largest illustrated installment'),money(Math.max(f.regular,f.final)))}</dl><p class="small muted stickyhint">${t('قيم توضيحية افتراضية. لا يوجد دفع أو تمويل حقيقي.','Fictional illustrative values. No real payment or financing.')}</p>`,'summary');}
function products(){return `<div class="pageintro"><h1>${t('اختر ما يناسب نشاطك','Choose for your business')}</h1><p>${t('منتجان افتراضيان لمالك نشاط صغير قائم. شروط المراجعة مفصّلة قبل التقديم.','Two fictional products for an individual owner of an established small business. Review conditions are explained before applying.')}</p></div><div class="twocol">${['inventory','equipment'].map(p=>panel(product(p),`<p>${p==='inventory'?t('لتجديد مخزون النشاط.','Replenish business stock.'):t('لشراء معدات إنتاجية.','Purchase productive equipment.')}</p><dl>${def(t('المبلغ','Amount'),p==='inventory'?money(100000)+' – '+money(1000000):money(500000)+' – '+money(3000000))}${def(t('الأشهر المتاحة','Available months'),ltr(p==='inventory'?'6 / 12':'12 / 18 / 24'))}${def(t('زيادة توضيحية مرة واحدة','One-time illustrative markup'),ltr(p==='inventory'?'5%':'8%'))}</dl><p class="small">${t('هوية، إثبات نشاط، ملخص مالي، و','Identity, business evidence, financial summary, and ')}${p==='inventory'?t('خطة شراء المخزون.','stock purchase plan.'):t('عرض سعر المعدات.','supplier quotation.')}</p><div class="sampleactions">${jump(t('ابدأ طلباً','Start application'),'apply',1,'primary')}</div>`)).join('')}</div>${notice(t('معايير المراجعة افتراضية، وتشمل مدة نشاط لا تقل عن ستة أشهر وفحص الغرض والتكلفة والقدرة على السداد والأدلة.','Review criteria are fictional and include six operating months, purpose, budget, repayment capacity and evidence checks.'))}`;}
function chooser(expired=false){return `<h1>${expired?t('انتهت جلستك التجريبية','Your demo session expired'):t('اختر هوية تجريبية','Choose a demo identity')}</h1>${notice(expired?t('المعلومات محجوبة. استعد نفس الهوية لاسترجاع الإدخال الموجود في هذا التبويب بعد فحص الوصول. لا تُعاد أي عملية تلقائياً.','Protected content is covered. Restore the same identity to recover this tab’s input after access checks. No action replays automatically.'):t('هويات وصلاحيات محاكية. البيانات محفوظة في متصفح العرض النهائي؛ هذا النموذج يعرض حالات مخططة فقط.','Simulated identities and permissions. The eventual demo saves in this browser; this walkthrough only depicts planned states.'))}${current.spec.resetDone?notice(t('اكتملت إعادة الضبط. استُعيدت 13 عينة والإعدادات الافتراضية، وانتهت كل الجلسات.','Reset completed. Restored 13 seeds and default settings; all sessions expired.')):''}<div class="twocol">${['A','B','C','R'].map(a=>panel(txt(names[a]),`<p class="muted">${a==='R'?t('موظفة مراجعة تجريبية','Demo reviewer'):t('متقدم تجريبي','Demo applicant')}</p><div class="sampleactions">${btn(expired&&a==='A'?t('استعادة نفس الهوية','Restore same identity'):t('استخدام هذه الهوية','Use this identity'),'identity',`data-actor="${a}"`,'primary')}</div>`)).join('')}</div><div class="sampleactions">${jump(t('المنتجات العامة','Public products'),'apply',0)}${jump(t('إعادة ضبط العرض','Reset demo'),'recovery',10)}</div>`;}
function recordCard(r){return `<article class="panel"><div class="row between"><strong>${entered(r.business)}</strong>${badge(r.status)}</div><p class="small">${ltr('RF-2026-'+r.id)} · ${product(r.product)}</p><p class="amount">${money(r.amount)}</p><p class="small muted">${date(r.submitted)}</p><div class="sampleactions">${btn(r.status==='draft'?t('متابعة المسودة','Resume draft'):r.status==='corrections'?t('عرض التعديلات المطلوبة','View requested corrections'):t('فتح الطلب','Open application'),'record',`data-id="${r.id}"`,'primary')}</div></article>`;}
function list(){const rows=seeds.filter(r=>r.owner===current.actor);return `<div class="pageintro row between"><div><h1>${t('طلباتي','My applications')}</h1><p>${t('كل طلباتك، مع الإجراء التالي لكل طلب.','All your applications, with the next action for each.')}</p></div>${jump(t('طلب جديد','New application'),'apply',0,'primary')}</div><div class="twocol">${rows.map(recordCard).join('')}</div>`;}
function errors(){const e=current.spec.error;if(!e)return '';return `<div class="notice error" tabindex="-1" id="validation-summary" role="alert"><strong>${t('راجع المعلومات قبل الإرسال','Review before submitting')}</strong><ul>${(e==='product'?[['amount',t('المبلغ خارج نطاق المعدات.','Amount is outside the Equipment range.')],['term',t('اختر مدة متاحة للمعدات.','Choose an available Equipment term.')]]:e==='explanation'?[['explanation',t('وصف الشراء مطلوب، من20 إلى500 حرف.','Purchase explanation is required, 20–500 characters.')]]:[['amount',t('التغيير يجب أن يختلف فعلياً عن المبلغ المطلوب تصحيحه.','The corrected amount must meaningfully change.')]]).map(([k,v])=>`<li><a href="#f-${k}" data-focus="f-${k}">${v}</a></li>`).join('')}</ul>${e==='unchanged'?`<p>${t('المستند له نفس محتوى الأصل. اختر نسخة مختلفة وواضحة.','The file has the same content as the original. Choose a different readable replacement.')}</p>`:''}</div>`;}
function feedback(){const x=current.spec;const lines={restored:['استُعيدت المسودة المحفوظة مع مستنداتها.','Restored the saved draft and its files.'],saved:['تم حفظ التقدم. لم تُرسل التغييرات للمراجعة. آخر حفظ ناجح: الآن.','Progress saved. Changes have not been sent for review. Last successful save: just now.'],'save-failed':['لم يُحفظ التقدم. المدخلات والملفات الجاهزة باقية؛ أعد الحفظ دون إعادة الرفع.','Progress was not saved. Input and ready files remain; retry saving without reuploading.'],'submit-failed':['لم يتم الإرسال. تبقى البيانات والملفات السابقة كما هي. أعد المحاولة صراحةً.','Submission did not complete. Prior saved data and files remain unchanged. Retry explicitly.'],'newer-input':['حُفظت القيم التي بدأت بها العملية. توجد كتابة أحدث لم تُحفظ.','Saved the values captured when the operation started. Newer typing is still unsaved.'],recovered:['استُعيد الإدخال بعد فحص الجلسة والوصول. لم يُحفظ أو يُرسل تلقائياً.','Input restored after session and access checks. Nothing saved or submitted automatically.'],submitted:['تم إرسال الطلب. يمكنك متابعة الحالة والسجل من هنا.','Application submitted. Follow its status and history here.'],resubmitted:['تم إرسال التصحيحات. الطلب قيد المراجعة والتحقق.','Corrections resubmitted. The application is under review and awaiting verification.']};return lines[x.feedback]?notice(txt(lines[x.feedback]),x.feedback.includes('failed')?'error':''):'';}
function documents(r,staff=false){const x=current.spec,labels=[...docLabels,r.product==='equipment'?['عرض سعر المعدات','Supplier quotation']:['خطة شراء المخزون','Stock purchase plan']];return labels.map((a,i)=>{const file=i===3?x.file:null;const missing=r.docs[i]==='missing'||x.error==='product'&&i===3;let state=staff?badge(r.docs[i],'doc'):missing?`<span class="pill">${t('لم يُضف مستند','No document added')}</span>`:`<span class="pill">${r.status==='draft'?t('محفوظ في المسودة','Saved in draft'):t('ضمن آخر إرسال','In submitted information')}</span>`;if(file&&!staff){state=`<span class="pill ${['failed','invalid','identical'].includes(file)?'failed':''}">${({invalid:t('نوع أو حجم غير صالح','Invalid type or size'),uploading:t('جارٍ التجهيز: 60%','Preparing: 60%'),failed:t('فشل التجهيز؛ الاختيار غير محفوظ','Preparation failed; selection unsaved'),ready:t('جاهز للحفظ؛ غير محفوظ','Ready to save; unsaved'),saved:t('محفوظ في مساحة العمل','Saved in workspace'),identical:t('نفس المحتوى؛ لم يتحقق الاستبدال','Same content; replacement unfulfilled')})[file]}</span>`;}return `<div class="doc"><span class="filemark" aria-hidden="true">${missing?'—':'PDF'}</span><div class="grow"><h3>${txt(a)}</h3><p class="filename">${missing?t('أضف المستند المطلوب','Add the required document'):ltr(`DEMO_${r.id}_${i+1}_مستند.pdf`)}</p>${state}${file==='uploading'?'<progress value="60" max="100" aria-label="Upload preparation progress">60%</progress>':''}${file==='ready'||file==='failed'?`<p class="small">${t('النسخة المحفوظة السابقة باقية حتى نجاح الحفظ.','The saved original remains until saving succeeds.')}</p>`:''}</div>${!missing?btn(t('معاينة','Preview'),'preview',`data-slot="${i}"`):''}</div>`;}).join('');}
function form(){const r={...current.record,...buffers},x=current.spec,step=x.step||'personal';const steps=[['personal','شخصي','Personal'],['business','النشاط','Business'],['financing','التمويل','Financing'],['documents','المستندات','Documents'],['review','المراجعة','Review']];let body='';if(step==='personal')body=`<div class="twocol">${field('name','الاسم الكامل','Full name',r.name)}${field('mobile','رقم الجوال','Mobile number',r.mobile,{numeric:true})}${field('city','المدينة','City',r.city)}${field('email','البريد الإلكتروني، اختياري','Email, optional',r.email,{optional:true})}</div>`;if(step==='business')body=`<div class="twocol">${field('business','اسم النشاط','Business name',r.business)}${field('activity','نوع النشاط','Business activity',r.activity,{hint:t('التجزئة / الخدمات / إنتاج صغير','Retail / Services / Small production')})}${field('address','عنوان النشاط','Business address',r.address,{full:true})}${field('since','شهر بدء النشاط','Operating since',r.since,{numeric:true,hint:t('شهر ميلادي، YYYY-MM','Gregorian year-month, YYYY-MM')})}${field('revenue','متوسط الإيرادات الشهرية','Average monthly revenue',r.revenue,{numeric:true})}${field('expenses','متوسط مصروفات التشغيل','Average operating expenses',r.expenses,{numeric:true})}</div>${notice(t('الأرقام عن يوليو وأغسطس وسبتمبر 2026، قبل أقساط هذا الطلب.','Figures cover July, August and September 2026, before repayments for this application.'))}`;if(step==='financing')body=`<p>${product(r.product)} · ${btn(t('تغيير المنتج','Change product'),'product')}</p><div class="twocol">${field('amount','مبلغ التمويل المطلوب','Requested amount',r.amount,{numeric:true})}${field('term','مدة السداد بالأشهر','Repayment term in months',r.term,{numeric:true})}${field('budget','تكلفة الشراء المتوقعة','Purchase budget',r.budget,{numeric:true,full:true})}${field('explanation','وصف الشراء والغرض منه','Purchase explanation',r.explanation,{area:true,full:true,hint:t('20–500 حرف.','20–500 characters.')})}</div>`;if(step==='documents')body=notice(t('PDF أوJPEG أوPNG، أكبر من صفر وحتى5,000,000 بايت. اختر ملفات تجريبية فقط.','PDF, JPEG or PNG, greater than zero and up to 5,000,000 bytes. Use fictional test files.'))+documents(r)+`<div class="sampleactions">${btn(t('عينات قبول ورفض الملفات','File acceptance examples'),'file-rules')}</div>`;if(step==='review')body=`<h3>${t('راجع قبل الإرسال','Review before submitting')}</h3><dl>${def(t('المتقدم','Applicant'),entered(r.name))}${def(t('الجوال','Mobile'),ltr(r.mobile))}${def(t('النشاط','Business'),entered(r.business))}${def(t('وصف الشراء','Purchase explanation'),entered(r.explanation))}${def(t('المنتج','Product'),product(r.product))}${def(t('المبلغ والمدة','Amount and term'),money(r.amount)+' · '+ltr(r.term))}</dl>${documents(r)}<p class="small">${t('الإرسال يحفظ وينشر القيم والمستندات معاً.','Submission saves and publishes input and documents together.')}</p>`;return `<h1>${t('طلب التمويل','Financing application')}</h1><div class="row between">${badge('draft')}<span class="small">${ltr('RF-2026-'+r.id)} · ${x.dirty?t('تغييرات غير محفوظة','Unsaved changes'):t('مسودة محفوظة','Saved draft')}</span></div><nav class="steps" aria-label="${t('خطوات الطلب','Application steps')}">${steps.map(([k,ar,en],i)=>btn(`${i+1}. ${t(ar,en)}`,'form-step',`data-step="${k}" ${step===k?'aria-current="step"':''}`)).join('')}</nav>${errors()}${feedback()}${x.newer?notice(t('توجد بيانات أحدث من تبويب آخر. احتُفظ بإدخالك. افحص الأحدث قبل الحفظ.','Newer data exists in another tab. Your input is retained. Inspect latest before saving.'),'warning'):''}${x.workspaceConflict?notice(t('أحدث حفظ: 250,000 ر.ي. إدخالك غير المطبق: 200,000 ر.ي. اختر الأحدث أو استبدله صراحةً بعد الفحص.','Latest saved: 250,000 YER. Your unapplied input: 200,000 YER. Use latest or explicitly replace it after inspection.'),'warning'):''}${x.unknown?notice(t('نتيجة الحفظ غير مؤكدة. نفحص آخر حالة وإيصال العملية قبل اقتراح إعادة المحاولة.','Save outcome is unknown. Inspect latest state and operation receipt before offering a retry.'),'info'):''}<div class="grid">${panel(txt(steps.find(a=>a[0]===step).slice(1)),body)}${summary(r)}</div>${overlayInline()}<div class="sampleactions no-print">${btn(t('اعرض تأكيد المغادرة','Preview leave prompt'),'leave')}${primaryNext()}</div>`;}
function targets(r){const missing=current.spec.requestedMissing||r.id==='1003',financial=r.id==='1012',quotation=r.id==='1013';if(missing)return [[t('ملخص الإيرادات والمصروفات','Revenue and expense summary'),t('أضف ملخص يوليو إلى سبتمبر لدعم المتوسطات المعلنة.','Add July–September evidence supporting the declared averages.')]];if(financial||quotation)return [[financial?txt(docLabels[2]):t('عرض سعر المعدات','Supplier quotation'),financial?t('استبدل الملخص غير المقروء بنسخة واضحة عن يوليو إلى سبتمبر.','Replace the unreadable summary with readable July–September evidence.'):t('أرسل عرض سعر واضحاً للمعدات والتكلفة الإجمالية.','Supply a readable equipment quotation and total cost.')]];return [[t('مبلغ التمويل المطلوب','Requested amount'),t('القسط 105,000 يتجاوز الحد التوضيحي80,000. خفّض المبلغ المطلوب.','105,000 installment exceeds the fictional 80,000 limit. Reduce the financing request.')],[t('خطة شراء المخزون','Stock purchase plan'),t('الخطة غير مقروءة. أرسل خطة واضحة توضح المشتريات وتكلفتها.','The plan is unreadable. Provide a readable plan showing purchases and total cost.')]];}
function applicationHistory(r,internal=false){let events=[[r.submitted||'2026-10-14',t('أُرسل الطلب','Application submitted')]];if(['review','corrections','approved','rejected'].includes(r.status))events.push([r.id==='1005'?'2026-07-04':r.id==='1004'?'2026-10-03':r.eventDate||'2026-10-14',t('بدأت المراجعة','Review started')]);if(r.status==='corrections'||current.spec.response)events.push([r.id==='1004'?'2026-10-04':r.eventDate||'2026-10-14',t('طُلبت تصحيحات محددة','Targeted corrections requested')]);if(current.spec.response)events.push(['2026-10-14',t('أُرسلت التصحيحات للمراجعة','Corrections resubmitted for review')]);if(['approved','rejected'].includes(r.status))events.push([r.eventDate,txt(statusLabels[r.status])]);if(internal&&current.spec.retainedReason)events.push(['2026-10-14',t('نقل إسناد محاكى إلى خالد','Simulated transfer to Khaled')]);return `<ol class="history">${events.map(([d,text])=>`<li><time>${date(d)}</time><strong>${text}</strong></li>`).join('')}</ol>`;}
function detail(){const r=current.record,x=current.spec;const isCorrection=r.status==='corrections';return `<div class="pageintro row between"><div><h1>${t('تفاصيل الطلب','Application details')}</h1><p>${ltr('RF-2026-'+r.id)} · ${entered(r.business)}</p></div>${badge(r.status)}</div>${feedback()}${r.status==='approved'?notice(t('تمت الموافقة على الشروط المرسلة بعد استيفاء معايير العرض.','Approved on the submitted terms after satisfying the demo criteria.')):''}${r.status==='rejected'?notice(t('يتطلب معيار العرض ستة أشهر من النشاط. يسجل هذا الطلب شهرين بين أغسطس وأكتوبر2026.','The demo requires six operating months. This application records two months between August and October 2026.'),'warning'):''}<div class="grid"><div class="stack">${isCorrection?panel(t('المطلوب منك','Action required'),targets(r).map(([a,b])=>`<div class="reviewtargets"><h3>${a}</h3><p>${b}</p></div>`).join('')+`<div class="sampleactions">${btn(t('أكمل التصحيحات','Complete corrections'),'open-correction','','primary')}</div>`):''}${panel(t('المعلومات المرسلة','Submitted information'),`<dl>${def(t('الاسم','Name'),entered(r.name))}${def(t('النشاط','Business'),entered(r.business))}${def(t('الجوال','Mobile'),ltr(r.mobile))}${def(t('الغرض','Purpose'),entered(r.explanation))}${def(t('تكلفة الشراء','Purchase budget'),money(r.budget))}</dl>`)}${panel(t('المستندات','Documents'),documents(r))}</div><aside class="stack">${summary(r)}${panel(t('سجل الطلب','Application history'),applicationHistory(r))}</aside></div><div class="sampleactions no-print">${btn(t('طباعة الملخص','Print summary'),'print-view')}${r.status==='approved'?btn(t('عرض السداد التوضيحي','View repayment illustration'),'repayment'):''}</div>`;}
function correction(){const r=current.record,x=current.spec;const amount=r.id==='1004',slot=r.id==='1012'?2:3;return `<h1>${t('إكمال التصحيحات','Complete corrections')}</h1><p>${ltr('RF-2026-'+r.id)} · ${badge('corrections')}</p>${notice(t('تُحفظ التغييرات في مساحة عملك فقط. لا يراها المراجع حتى ترسل الرد كاملاً.','Saved changes stay in your workspace. The reviewer sees them only after you resubmit the complete response.'))}${errors()}${feedback()}<div class="grid">${panel(t('الأهداف المطلوبة','Requested targets'),targets(r).map(([a,b])=>`<div class="reviewtargets"><h3>${a}</h3><p>${b}</p></div>`).join('')+(amount?field('amount','المبلغ المصحح','Corrected amount',x.workspaceAmount||r.amount,{numeric:true,hint:t('الأساس الثابت600,000 ر.ي. حد القسط80,000 ر.ي.','Fixed baseline 600,000 YER. Installment limit 80,000 YER.')}):'')+`<div class="doc"><span class="filemark">PDF</span><div class="grow"><h3>${slot===2?txt(docLabels[2]):r.product==='equipment'?t('عرض سعر المعدات','Supplier quotation'):t('خطة شراء المخزون','Stock purchase plan')}</h3><p>${x.file==='ready'?t('جاهز للحفظ؛ غير منشور','Ready to save; unpublished'):x.file==='identical'?t('نفس المحتوى؛ يلزم بديل مختلف','Same content; choose a different replacement'):t('النسخة الأصلية غير المقروءة','Unreadable original')}</p></div>${btn(t('معاينة','Preview'),'preview',`data-slot="${slot}"`)}</div>`)}<aside class="stack">${summary({...r,amount:x.workspaceAmount||r.amount})}${panel(t('معلومات ثابتة','Locked information'),`<dl>${def(t('المنتج','Product'),product(r.product))}${def(t('تكلفة الشراء','Purchase budget'),money(r.budget))}${def(t('المدة','Term'),ltr(r.term))}${def(t('الفترة المالية','Evidence window'),t('يوليو إلى سبتمبر2026','July–September 2026'))}</dl><p class="small">${t('تغيير الأهداف يحتاج طلب تصحيح جديداً من المراجع.','Changing targets requires another correction request from the reviewer.')}</p>`)}</aside></div><div class="sampleactions">${primaryNext()}${btn(t('خيارات المغادرة','Leave options'),'leave')}</div>`;}
function notifications(){const r=current.actor;const items=seeds.filter(s=>s.owner===r&&['approved','rejected','corrections'].includes(s.status));return `<h1>${t('التنبيهات','Notifications')}</h1><p>${t('طلبات تصحيح وقرارات نهائية فقط. لا إشعارات لحفظ المسودة أو إرسالها.','Correction requests and final decisions only. Draft saves and submissions do not create notifications.')}</p><div class="stack" style="margin-top:20px">${items.map(a=>panel(txt(statusLabels[a.status]),`<div class="row between"><p>${ltr('RF-2026-'+a.id)} · ${entered(a.business)}</p><span class="pill" id="read-${a.id}">${t('غير مقروء','Unread')}</span></div><p class="small">${date(a.eventDate)}</p><div class="sampleactions">${btn(t('فتح الطلب','Open application'),'record',`data-id="${a.id}"`,'primary')}${btn(t('تعليم كمقروء','Mark read'),'mark-read',`data-id="${a.id}"`)}</div>`)).join('')}</div>`;}
function queueRows(){const q=queue.q.toLocaleLowerCase();let rows=seeds.filter(r=>r.status!=='draft'&&(queue.status==='all'||r.status===queue.status)&&(queue.product==='all'||r.product===queue.product)&&(queue.assignment==='all'||(queue.assignment==='none'?!r.assignee:r.assignee===queue.assignment))&&(!q||[r.id,'RF-2026-'+r.id,r.name,names[r.owner][1],r.business].join(' ').toLocaleLowerCase().includes(q)));rows.sort((a,b)=>queue.sort==='amount-desc'?b.amount-a.amount||a.id.localeCompare(b.id):queue.sort==='amount-asc'?a.amount-b.amount||a.id.localeCompare(b.id):queue.sort==='date-asc'?a.submitted.localeCompare(b.submitted)||a.id.localeCompare(b.id):b.submitted.localeCompare(a.submitted)||a.id.localeCompare(b.id));queue.page=Math.min(Math.max(1,queue.page),Math.max(1,Math.ceil(rows.length/5)));return rows;}
function selectFilter(id,label,items,value){return `<div><label for="${id}">${label}</label><select id="${id}" data-filter="${id}">${items.map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('')}</select></div>`;}
function assignee(r){return r.assignee==='R'?t('مسند إليك','Assigned to you'):r.assignee?txt(names[r.assignee]):t('غير مسند','Unassigned');}
function queueScreen(){return `<h1>${t('قائمة الطلبات','Application queue')}</h1><div class="counts">${[[12,t('كل الطلبات','All applications')],[4,t('مُرسل','Submitted')],[3,t('قيد المراجعة','Under review')],[3,t('تعديلات مطلوبة','Corrections requested')],[2,t('قرارات نهائية','Final decisions')]].map(([n,s])=>`<div><span class="small">${s}</span><strong>${n}</strong></div>`).join('')}</div><div class="toolbar"><div><label for="queue-search">${t('ابحث بالمرجع أو الاسم أو النشاط','Search reference, name or business')}</label><input id="queue-search" value="${esc(queue.q)}" type="search"></div>${selectFilter('status',t('الحالة','Status'),[['all',t('كل الحالات','All statuses')],...Object.entries(statusLabels).filter(([k])=>k!=='draft').map(([k,v])=>[k,txt(v)])],queue.status)}${selectFilter('product',t('المنتج','Product'),[['all',t('كل المنتجات','All products')],['inventory',product('inventory')],['equipment',product('equipment')]],queue.product)}${selectFilter('assignment',t('الإسناد','Assignment'),[['all',t('كل الإسنادات','All assignments')],['R',t('مسند إليك','Assigned to you')],['K',txt(names.K)],['none',t('غير مسند','Unassigned')]],queue.assignment)}${selectFilter('sort',t('الفرز','Sort'),[['date-desc',t('الأحدث إرسالاً','Newest submitted')],['date-asc',t('الأقدم إرسالاً','Oldest submitted')],['amount-desc',t('المبلغ: الأعلى','Amount: highest')],['amount-asc',t('المبلغ: الأقل','Amount: lowest')]],queue.sort)}</div><div id="queue-results">${queueResults()}</div><p class="small muted">${t('الفلاتر والفرز تفضيلات محفوظة في العرض النهائي. البحث والصفحة في الرابط؛ هذا النموذج يحتفظ بها في الذاكرة فقط.','Filters and sort are saved preferences in the eventual demo. Search and page belong in the URL; this prototype keeps them in memory only.')}</p>`;}
function queueResults(){const rows=queueRows(),page=rows.slice((queue.page-1)*5,queue.page*5);if(!rows.length)return `<div class="panel empty"><h2>${t('لا توجد نتائج مطابقة','No matching applications')}</h2><p>${t('جرّب بحثاً أقصر أو غيّر الفلاتر.','Try a shorter search or change filters.')}</p><div class="sampleactions">${btn(t('مسح البحث','Clear search'),'clear-search')}${btn(t('إعادة ضبط الفلاتر','Reset filters'),'clear-filters')}</div></div>`;return `<div class="tablewrap queue-table"><table><caption class="small" style="padding:10px" aria-live="polite">${rows.length} ${t('نتيجة','results')}</caption><thead><tr>${[t('الطلب والمتقدم','Application / applicant'),t('المنتج والمبلغ','Product / amount'),t('الحالة','Status'),t('الإسناد','Assignment'),t('الإرسال','Submission'),t('الإجراء','Action')].map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${page.map(r=>`<tr><td><strong>${entered(r.name)}</strong><br>${entered(r.business)}<br>${ltr('RF-2026-'+r.id)}</td><td>${product(r.product)}<br>${money(r.amount)}</td><td>${badge(r.status)}</td><td>${assignee(r)}</td><td>${date(r.submitted)}</td><td>${btn(t('فتح','Open'),'record',`data-id="${r.id}" aria-label="${t('فتح الطلب','Open application')} ${r.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="mobilecards">${page.map(r=>`<article class="panel"><div class="row between"><strong>${entered(r.name)}</strong>${badge(r.status)}</div><p>${entered(r.business)}</p><p>${ltr('RF-2026-'+r.id)} · ${assignee(r)}</p><p>${product(r.product)} · ${money(r.amount)}</p><p class="small">${date(r.submitted)}</p>${btn(t('فتح الطلب','Open application'),'record',`data-id="${r.id}"`)}</article>`).join('')}</div><div class="row between"><span id="result-count" role="status">${t('الصفحة','Page')} ${queue.page} / ${Math.ceil(rows.length/5)} · ${rows.length} ${t('نتيجة','results')}</span><div class="row">${Array.from({length:Math.ceil(rows.length/5)},(_,i)=>btn(String(i+1),'page',`data-page="${i+1}" aria-label="${t('صفحة','Page')} ${i+1}" ${queue.page===i+1?'aria-current="page"':''}`)).join('')}</div></div>`;}
function review(){const r=current.record,x=current.spec,can=r.assignee==='R'&&r.status==='review';return `<div class="pageintro"><div class="row between"><h1>${entered(r.name)}</h1>${badge(r.status)}</div><p>${ltr('RF-2026-'+r.id)} · ${entered(r.business)}</p><div class="row between"><strong>${assignee(r)}</strong>${!['approved','rejected'].includes(r.status)?btn(t('إدارة الإسناد','Manage assignment'),'assignment'):''}</div></div>${!can?notice(r.status==='submitted'?t('استلم الإسناد ثم ابدأ المراجعة لتتاح إجراءات الفحص.','Claim the application, then start review to enable assessment.'):r.status==='corrections'?t('بانتظار رد المتقدم. يمكنك قراءة آخر إرسال وإضافة ملاحظة إن كنت المراجع المسند.','Waiting for the applicant. Read the submitted information and add a note if assigned.'):t('عرض للقراءة. لا تملك صلاحية تعديل المراجعة في هذه الحالة أو الإسناد.','Read-only view. Review changes are unavailable for this state or assignment.'),'info'):''}${x.retainedReason?notice(t('سبب القرار السابق محفوظ كنص غير مطبق. أُلغي التأكيد السابق. افحص أحدث معلومات قبل إعادة استخدامه.','Previous decision reason retained as unapplied text. Prior confirmation invalidated. Inspect latest information before reusing it.'),'warning'):''}<nav class="row no-print" aria-label="${t('أقسام المراجعة','Review sections')}">${[['information',t('المعلومات','Information')],['documents',t('المستندات','Documents')],['checks',t('الفحوص','Checks')],['activity',t('السجل','Activity')]].map(([id,title])=>`<a href="#${id}" data-focus="${id}">${title}</a>`).join('')}</nav><div class="grid" style="margin-top:20px"><div class="stack"><section class="panel" id="information" tabindex="-1"><h2>${t('آخر معلومات مرسلة','Last submitted information')}</h2>${x.response?notice(t('تغير المبلغ من600,000 إلى450,000. خطة المخزون استُبدلت. مساحة المتقدم الخاصة لا تظهر هنا.','Amount changed from 600,000 to 450,000. Stock plan replaced. The applicant’s private workspace is not visible.')):''}<dl>${def(t('مبلغ التمويل','Financing amount'),money(r.amount))}${def(t('المدة','Term'),ltr(r.term))}${def(t('تكلفة الشراء','Purchase budget'),money(r.budget))}${def(t('متوسط الإيرادات','Average revenue'),money(r.revenue))}${def(t('متوسط المصروفات','Average expenses'),money(r.expenses))}${def(t('شهر بدء النشاط','Operating since'),ltr(r.since))}${def(t('الغرض','Purpose'),entered(r.explanation))}</dl></section><section class="panel" id="documents" tabindex="-1"><h2>${t('المستندات وتقييمها','Documents and assessments')}</h2>${documents(r,true)}${x.response?notice(t('قبول الخطة البديلة يحقق هدف المستند. المبلغ يحتاج تحققاً مستقلاً.','Accepting the replacement plan verifies its document target. The amount requires separate verification.')):''}</section><section class="panel" id="activity" tabindex="-1"><h2>${t('النشاط والسجل','Activity and history')}</h2>${applicationHistory(r,true)}<p class="small muted">${t('أحداث الإسناد والتقييم والملاحظات داخلية.','Assignment, assessments and notes are internal.')}</p></section></div><aside class="stack"><section class="panel" id="checks" tabindex="-1"><h2>${t('قائمة المراجعة الثابتة','Fixed review checklist')}</h2>${checkLabels.map((a,i)=>`<div class="check"><span>${txt(a)}</span>${badge(r.checks[i],'check')}</div>`).join('')}${x.recheck?`<p class="checksnotice">${t('أُعيدت أربعة فحوص. مدة النشاط بقيت مستوفاة لأنها لم تتأثر.','Four checks reset. Operating history remains Passed because its dependencies did not change.')}</p>`:''}<p class="small stickyhint">${t('الفحوص الرقمية لا تسمح بتمرير نتيجة فاشلة. اتساق الأدلة وحده لا يبرر الرفض.','Numeric checks cannot override a failed rule to Passed. Evidence consistency alone cannot justify rejection.')}</p>${x.response?`<h3>${t('تحقق التصحيحات','Correction verification')}</h3><p>${t('المبلغ والخطة','Amount and plan')}: ${x.verified?t('تم التحقق','Verified'):t('بانتظار التحقق','Awaiting verification')}</p>`:''}</section>${summary(r)}${panel(t('ملاحظة داخلية','Internal note'),field('note','نص الملاحظة','Note text',x.noteDraft||'',{area:true,optional:true,readonly:!['review','corrections','approved','rejected'].includes(r.status)||r.assignee!=='R',hint:t('مرئية للموظفين فقط. لا تُرسل عند المغادرة.','Staff only. Never sent on departure.')})+btn(t('اعرض سياسة حفظ الملاحظة','Inspect note save behavior'),'note-policy'))}</aside></div>${overlayInline()}<div class="sampleactions no-print">${btn(t('العودة إلى القائمة','Back to queue'),'queue')}${primaryNext()}${btn(t('الملخص القابل للطباعة','Printable summary'),'print-view')}</div>`;}
function requestScreen(){const r=current.record,x=current.spec;return `<h1>${x.repeat?t('جولة تصحيح جديدة','New correction round'):t('طلب تصحيحات','Request corrections')}</h1><p>${ltr('RF-2026-'+r.id)} · ${entered(r.name)}</p>${notice(t('أضف الأهداف التي تحتاج تغييراً فعلياً، مع سبب لكل هدف. لا يمكن استهداف المنتج أو فتح كل الحقول.','Include only targets needing actual changes, with a reason for each. Product cannot be targeted; unrelated fields stay locked.'))}<div class="grid">${panel(t('الأهداف والأسباب','Targets and reasons'),targets(r).filter((a,i)=>!x.repeat||i===1).map(([a,b],i)=>`<div class="reviewtargets"><h3>${a}</h3>${field('reason-'+i,'سبب ظاهر للمتقدم','Applicant-visible reason',b,{area:true})}</div>`).join('')+notice(t('قبل الإرسال: مراجعة قائمة الأهداف والأسباب ثم تأكيد إرسال الطلب. المغادرة تتيح تجاهل أو بقاء فقط.','Before sending: review all targets and reasons, then confirm the request. Leaving offers only Discard or Stay.')))}${panel(t('ما سيتغير','What changes'),`<p>${t('تتحول الحالة إلى تعديلات مطلوبة. تُحفظ نسخة أساس ثابتة ويُنشأ تنبيه واحد للمتقدم.','Status becomes Corrections requested. Capture a fixed baseline and create one applicant notification.')}</p><p>${t('تتوقف إجراءات المراجعة إلى أن يعود الرد. الملاحظات الداخلية تبقى متاحة للمراجع المسند.','Pause review actions until resubmission. Internal notes remain available to the assigned reviewer.')}</p>`)}</div><div class="sampleactions">${btn(t('معاينة التأكيد','Preview confirmation'),'request-confirm')}${btn(t('خيارات المغادرة','Leave options'),'leave')}${primaryNext()}</div>`;}
function decision(){const r=current.record,x=current.spec,reason=x.reject?t('يتطلب معيار العرض ستة أشهر من النشاط؛ يسجل الطلب شهرين فقط.','The demo requires six operating months; the application records only two.'):t('استوفى الطلب معايير العرض بالمبلغ والمدة المرسلين بعد فحص الأدلة.','The application satisfies the demo criteria on its submitted amount and term after evidence review.');return `<h1>${x.reject?t('تأكيد الرفض','Confirm rejection'):t('تأكيد الموافقة','Confirm approval')}</h1><p>${ltr('RF-2026-'+r.id)} · ${entered(r.name)}</p>${x.conflict?notice(t('تغير الطلب منذ فتحه. لم يسجل القرار. حمّل أحدث نسخة وافحص الإسناد قبل المحاولة من جديد.','The application changed since you opened it. No decision was recorded. Load latest and inspect assignment before trying again.'),'error'):''}${x.stale?notice(t('محاكاة: انتقل الإسناد في البيانات المحفوظة إلى خالد. هذا العرض وحده ما زال قديماً.','Simulation: saved assignment moved to Khaled. This initiating view alone remains stale.'),'warning'):''}${x.fresh?notice(t('فُحصت النسخة الحالية بعد استعادة الإسناد. يلزم تأكيد جديد وصريح.','Current information inspected after reclaiming. A fresh explicit confirmation is required.')):''}<div class="grid">${panel(t('السبب والتأكيد','Reason and confirmation'),field('decisionReason','سبب ظاهر للمتقدم','Applicant-visible reason',reason,{area:true})+`<dl>${def(t('القرار','Decision'),x.reject?t('رفض نهائي','Final rejection'):t('موافقة نهائية','Final approval'))}${def(t('الطلب','Application'),ltr('RF-2026-'+r.id))}${def(t('المبلغ والمدة','Amount and term'),money(r.amount)+' · '+ltr(r.term)+' '+t('شهراً','months'))}</dl>${notice(x.reject?t('معيار مدة النشاط فاشل. نتائج المستندات غير المكتملة لا تتحول إلى قبول.','Operating history failed. Incomplete document reviews remain incomplete.'):t('كل المستندات مقبولة وكل الفحوص مستوفاة. الموافقة تقبل الشروط المرسلة كما هي.','All documents accepted and all checks passed. Approval accepts the submitted terms.'),'warning')}<div class="sampleactions">${btn(x.conflict?t('تحميل الأحدث','Load latest'):t('معاينة حوار التأكيد','Preview confirmation dialog'),x.conflict?'next':'decision-confirm','',x.reject?'danger':'primary')}</div>`)}${summary(r)}</div><p class="small muted stickyhint">${t('عند انتظار النتيجة، يعطل التأكيد المتكرر. الفشل المؤكد لا ينشئ قراراً؛ النتيجة المجهولة تحتاج فحص الحالة.','Disable duplicate confirmation while pending. Confirmed failure creates no decision; unknown completion requires state inspection.')}</p>`;}
function repayment(){const r=current.record,f=financing(r),historical=r.id==='1005',done=historical?2:0,first=historical?new Date('2026-08-15T12:00:00Z'):new Date('2026-11-15T12:00:00Z');return `<h1>${t('جدول سداد توضيحي افتراضي','Fictional repayment illustration')}</h1><p>${ltr('RF-2026-'+r.id)} · ${badge('approved')}</p>${notice(t('هذا جدول للقراءة فقط. لا يمثل حساب دفع أو مبالغ محصلة فعلياً. تواريخ الاستحقاق لا تغيّر حالة الأقساط تلقائياً.','Read-only illustration. This is not a payment account or a record of actual collections. Due dates do not automatically change installment status.'))}<div class="grid">${panel(t('الأقساط','Installments'),`<table class="schedule-table"><thead><tr><th>${t('القسط','Entry')}</th><th>${t('التاريخ','Due date')}</th><th>${t('المبلغ','Amount')}</th><th>${t('الحالة','Status')}</th></tr></thead><tbody>${Array.from({length:r.term},(_,i)=>{const d=new Date(first);d.setUTCMonth(d.getUTCMonth()+i);return `<tr><td>${i+1}</td><td>${date(d.toISOString().slice(0,10))}</td><td>${money(i===r.term-1?f.final:f.regular)}</td><td><span class="pill ${i<done?'approved':''}">${i<done?t('مكتمل','Completed'):t('قادم','Upcoming')}</span></td></tr>`;}).join('')}</tbody></table>`)}<aside class="stack">${summary(r)}${panel(t('حالة المثال','Example totals'),`<dl>${def(t('المبلغ المكتمل','Completed amount'),money(done*f.regular))}${def(t('المبلغ المتبقي','Remaining amount'),money(f.total-done*f.regular))}</dl>`)}</aside></div>`;}
function printView(){const r=current.record;const unpublished=r.status==='draft'||r.status==='corrections';return `<article class="printpage"><p class="stamp">DEMO / تجريبي</p><h1>${t('ملخص طلب التمويل','Financing application summary')}</h1><p>${ltr('RF-2026-'+r.id)} · ${badge(r.status)}</p>${unpublished?notice(r.status==='draft'?t('مسودة غير مرسلة. يعرض الملخص آخر تقدم محفوظ فقط.','Unsubmitted draft. This summary shows only the last saved progress.'):t('آخر معلومات مرسلة. مساحة التصحيحات الخاصة غير مدرجة في هذه النسخة.','Last submitted information. The private correction workspace is excluded from this copy.')):''}<div class="twocol"><section class="panel"><h2>${t('المتقدم والنشاط','Applicant and business')}</h2><dl>${def(t('الاسم','Name'),entered(r.name))}${def(t('الجوال','Mobile'),ltr(r.mobile))}${def(t('المدينة','City'),entered(r.city))}${def(t('البريد الإلكتروني','Email'),ltr(r.email))}${def(t('النشاط','Business'),entered(r.business))}${def(t('العنوان','Address'),entered(r.address))}${def(t('شهر بدء النشاط','Operating since'),ltr(r.since))}${def(t('الإيرادات / المصروفات','Revenue / expenses'),money(r.revenue)+' / '+money(r.expenses))}</dl></section>${summary(r)}</div><section class="panel"><h2>${t('الغرض والمستندات','Purpose and documents')}</h2><p>${entered(r.explanation||t('لم يُكتب بعد','Not entered'))}</p><dl>${def(t('تكلفة الشراء','Purchase budget'),money(r.budget))}${[...docLabels,r.product==='equipment'?['عرض سعر المعدات','Supplier quotation']:['خطة شراء المخزون','Stock purchase plan']].map((a,i)=>def(txt(a),r.docs[i]==='missing'?t('لم يُضف','Not provided'):ltr(`DEMO_${r.id}_${i+1}_مستند.pdf`))).join('')}</dl></section>${['corrections','rejected','approved'].includes(r.status)?panel(t('الأسباب الظاهرة للمتقدم','Applicant-visible reasons'),r.status==='corrections'?targets(r).map(([a,b])=>`<p>${a}: ${b}</p>`).join(''):r.status==='rejected'?t('معيار العرض يتطلب ستة أشهر من النشاط؛ يسجل الطلب شهرين.','The demo requires six operating months; this application records two.'):t('استوفى الطلب شروط العرض بالمبلغ والمدة المرسلين.','The application satisfies the demo criteria on its submitted amount and term.')):''}${r.status!=='draft'?panel(t('سجل الطلب','Application history'),applicationHistory(r)):''}<p class="small">${t('أُعد في14 أكتوبر2026. هوية ومنتجات وشروط افتراضية.','Prepared 14 October 2026. Fictional identity, products and terms.')}</p><div class="sampleactions no-print">${btn(t('طباعة أو حفظ PDF','Print or save PDF'),'print','','primary')}${btn(t('العودة إلى الطلب','Back to application'),'back-record')}</div></article>`;}
function startup(){return `<h1>${t('تجهيز العرض التجريبي','Preparing the demo')}</h1>${current.spec.startupError?notice(t('تعذر فتح البيانات المحلية. لم تُحذف معلوماتك. أغلق التبويب الذي يمنع الترقية إن وجد، ثم أعد المحاولة. البيانات غير المدعومة أو التالفة تحتاج استرداداً مؤكداً.','Local data could not be opened. Nothing was deleted. Close a tab blocking the upgrade, if present, then retry. Unsupported or damaged data requires explicit recovery.'),'error'):`<section aria-busy="true" aria-label="${t('جارٍ تجهيز التخزين والعينات','Preparing storage and samples')}"><p>${t('جارٍ فتح التخزين وتجهيز العينات والتحقق من الجلسة…','Opening storage, preparing samples and checking the session…')}</p><div class="skeleton"></div><div class="skeleton" style="width:50%"></div></section>`}<div class="sampleactions">${current.spec.startupError?btn(t('معاينة إعادة المحاولة','Preview retry'),'retry-startup','','primary'):''}${jump(t('المنتجات','Products'),'apply',0)}${jump(t('معرض المكونات','Components'),'recovery',13)}${jump(t('إعادة ضبط مؤكدة','Confirmed reset'),'recovery',10)}</div><p class="small stickyhint">${t('بعد الجاهزية تعمل البيانات والعينات المحلية دون اتصال. فتح التطبيق لأول مرة دون اتصال خارج نطاق هذا العرض. لا حفظ صامت في الذاكرة عند فشل التخزين.','After readiness, local data and samples work offline. Fresh offline launches are outside scope. Storage failure never silently falls back to memory-only saving.')}</p>`;}
function unavailable(){return `<section class="panel empty"><h1>${t('هذا الطلب غير متاح','This application is unavailable')}</h1><p>${t('تعذر فتح هذا الرابط بالهوية الحالية.','This link cannot be opened with the current identity.')}</p><div class="sampleactions">${btn(t('العودة إلى صفحتي','Go to my home'),'home','','primary')}${btn(t('تبديل الهوية','Switch identity'),'switch')}</div></section>`;}
function resetScreen(){return `<h1>${t('إعادة ضبط العرض','Reset demo')}</h1>${notice(t('ستُستبدل كل الطلبات والملفات بالتجهيزات الأصلية. ستُمسح التفضيلات والجلسات والعمل غير المحفوظ في كل تبويبات هذا العرض في المتصفح.','Replace all applications and files with the original seeds. Clear preferences, sessions and unfinished work in every demo tab in this browser.'),'warning')}${current.spec.resetFailed?notice(t('لم تكتمل إعادة الضبط. مجموعة البيانات السابقة باقية، وكذلك العمل غير المحفوظ. عالج مشكلة التخزين ثم أعد المحاولة.','Reset did not complete. The previous dataset and unfinished work remain. Recover storage, then retry.'),'error'):''}${panel(t('ما سيُستعاد','What will be restored'),`<ul><li>${t('13 طلباً وملفاتها التجريبية، منها مسودة و12 طلباً في قائمة المراجعة.','13 applications and sample files, including one draft and 12 staff queue records.')}</li><li>${t('اللغة العربية، كل الحالات، الفرز حسب أحدث إرسال، دون جلسة نشطة.','Arabic, all statuses, newest-submitted sort, and no active session.')}</li></ul><label class="resetconfirm"><input type="checkbox" id="reset-check"><span>${t('أفهم أن إعادة الضبط تشمل جميع تبويبات العرض والعمل غير المحفوظ فيها.','I understand that reset affects all demo tabs and their unfinished work.')}</span></label>${btn(t('معاينة إعادة الضبط الناجحة','Preview successful reset'),'reset-confirm','disabled','danger')}`)}`;}
function gallery(){return `<h1>${t('معرض المكونات','Component gallery')}</h1><div class="twocol">${panel(t('الهوية والتركيز','Identity and focus'),`<p style="font-size:25px">${t('خطوة واضحة لطلبك','A clear next step')}</p><div class="swatches">${['#0b6458','#192f2c','#e4efea','#f5f7f4'].map(c=>`<span style="background:${c};border:1px solid #ccd9d2"></span>`).join('')}</div><div class="sampleactions">${btn(t('زر أساسي','Primary action'),'sample','','primary focusdemo')}${btn(t('حوار المعاينة','Preview dialog'),'preview','data-slot="0"')}</div>`)}${panel(t('حالات منفصلة','Distinct statuses'),`<p>${t('حالة الطلب','Application status')}</p><div class="row">${Object.keys(statusLabels).map(k=>badge(k)).join('')}</div><p class="stickyhint">${t('تقييم المستند، للموظف فقط','Document assessment, staff only')}</p><div class="row">${Object.keys(docStates).map(k=>badge(k,'doc')).join('')}</div>`)}${panel(t('أخطاء مرتبطة بالحقول','Linked validation'),`<div class="notice error" id="gallery-errors" tabindex="-1"><a href="#sample-amount" data-focus="sample-amount">${t('المبلغ أقل من الحد المسموح.','Amount is below the permitted minimum.')}</a></div><label for="sample-amount">${t('مبلغ التمويل المطلوب','Requested amount')}</label><input id="sample-amount" value="٥٠٠٠٠" dir="ltr" inputmode="numeric" aria-invalid="true" aria-describedby="sample-error"><p id="sample-error">${t('أدخل100,000 إلى1,000,000 ر.ي.','Enter 100,000–1,000,000 YER.')}</p>`)}${panel(t('الكتابة المختلطة','Mixed-direction content'),`<dl>${def(t('الاسم كما أُدخل','Name as entered'),entered('ورشة المدار / Al-Madar 02'))}${def(t('مرجع','Reference'),ltr('RF-2026-1007'))}${def(t('ملف','File'),ltr('quotation_معدات-02.pdf'))}${def(t('جوال','Mobile'),ltr('+000000000001'))}${def(t('مبلغ','Amount'),money(1200000))}${def(t('تاريخ ميلادي','Gregorian date'),date('2026-10-14'))}</dl>`)}</div>`;}
function overlayInline(){const key=current.spec.overlay;return key?notice(t('تتضمن هذه الخطوة حواراً مقترحاً. ','This step includes a proposed dialog. ')+btn(t('فتح الحوار','Open dialog'),key==='preview-error'?'preview-error':key==='transfer'?'assignment':key==='product'?'product':'leave'),'warning'):'';}
function inspector(){const {spec:x,record:r}=current,protectedHidden=['expired','unavailable','startup','signin'].includes(x.screen);if(protectedHidden)return `<details class="inspector"><summary>${t('حالة النموذج المخططة','Planned prototype state')}</summary><p>${t('لا تُعرض معلومات طلب محمي في هذه الحالة. التخزين الحقيقي والجلسات غير منفذة في هذا النموذج.','This state reveals no protected application information. Real storage and sessions are not implemented in this prototype.')}</p></details>`;return `<details class="inspector"><summary>${t('حالة المشهد المخططة وملاحظات المراجعة','Planned scene state and review notes')}</summary><dl>${def(t('الهوية','Identity'),x.actor?txt(names[x.actor]):t('زائر','Visitor'))}${def(t('المسار المقترح','Proposed route'),ltr(current.route))}${def(t('حالة الطلب','Application status'),badge(r.status))}${def(t('تغييرات الشاشة','Screen input'),x.dirty||Object.keys(buffers).length?t('غير محفوظة','Unsaved'):t('لا تعديل جديد','No new edits'))}${def(t('إدخال المتقدم','Applicant input'),x.workspaceAmount?money(x.workspaceAmount):money(r.amount))}${def(t('آخر مبلغ مرسل','Last submitted amount'),r.status==='draft'?t('لا يوجد','None'):money(r.amount))}${def(t('الملف الجديد','New attachment'),x.file?esc(x.file):t('لا اختيار جديد','No new selection'))}${def(t('مدة العملية النموذجية','Mock latency'),ltr('400 ms / 1,500 ms'))}${def(t('مدة تجهيز الملفات','Preparation latency'),ltr('1,200 ms / 4,000 ms'))}${current.actor==='R'?def(t('نتائج الفحوص','Checks'),r.checks.map(k=>txt(checkStates[k])).join(' / ')):''}</dl><p class="small">${t('الأزرار الإرشادية تحمل حالات مخططة مستقلة. التغيير بين المشاهد يعيد ضبط المثال. لا تخزين ولا مصادقة ولا ملفات فعلية.','Walkthrough buttons load independent planned states. Changing scenes resets the example. No real persistence, authentication or file bytes.')}</p></details>`;}
function header(){const actor=current.actor;return `<div class="introflag">${t('رِفد عرض افتراضي · هذا نموذج استعراض مؤقت في الذاكرة فقط','RIFD fictional demo · This throwaway walkthrough uses memory only')}</div><header class="topbar"><div class="brand"><span class="mark" aria-hidden="true"><i></i><i></i><i></i></span><strong>${t('رِفد','RIFD')}</strong></div><div class="row"><span class="small">${actor?txt(names[actor]):t('زائر','Visitor')} ${actor==='R'?'· '+t('موظفة مراجعة','Reviewer'):''}</span>${btn(t('English','العربية'),'language',`lang="${lang==='ar'?'en':'ar'}"`)}${btn(t('تبديل الهوية','Switch identity'),'switch')}${btn(t('أدوات العرض','Demo controls'),'controls')}</div></header>`;}
function guide(){return `<section class="guide" aria-label="${t('دليل الاستعراض','Walkthrough guide')}"><div class="row between"><strong>${t('استعراض تدفق الشاشات · التصميم أ','Screen-flow walkthrough · Guided A')}</strong><a href="README.md">${t('دليل المراجعة','Review guide')}</a></div><p class="small">${t('هل توضح هذه الشاشات المكان والخطوة التالية وما حُفظ أو أُرسل؟ الأزرار أدناه تحمل حالات مخططة. تبديل المشهد يعيد المثال؛ تحديث الصفحة يعيد المدخلات.','Do these screens make location, next action, and saved versus submitted work clear? Buttons below load planned states. Scene changes reset the example; refresh clears edits.')}</p><nav class="tabs" aria-label="${t('جولات الاستعراض','Walkthrough chapters')}">${btn(t('جولة مختصرة، 7 محطات','Short tour, 7 stops'),'chapter',`data-chapter="tour" aria-current="${chapter==='tour'}"`)}${chapters.map(c=>btn(txt(c.title),'chapter',`data-chapter="${c.key}" aria-current="${chapter===c.key}"`)).join('')}</nav><div class="selectstep"><label for="scene-select">${t('المشهد','Scene')}</label><select id="scene-select">${Array.from({length:sceneCount()},(_,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1} / ${sceneCount()} · ${txt(specAt(i).label)}</option>`).join('')}</select>${btn(t('مسارات مقترحة','Proposed routes'),'routes')}</div></section><section class="walknote"><div><h2 id="scene-heading" tabindex="-1">${txt(current.spec.label)}</h2><p>${txt(current.spec.note)}</p></div><div class="walkbuttons">${btn(t('السابق','Previous'),'previous',index===0?'disabled':'')}${primaryNext()}</div></section>`;}
function render(focus=false){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t('رِفد · استعراض تدفق الشاشات','RIFD · Screen-flow walkthrough');const screens={products,signin:()=>chooser(),list,form,detail,correction,notifications,queue:queueScreen,review,request:requestScreen,decision,repayment,print:printView,expired:()=>chooser(true),unavailable,startup,reset:resetScreen,gallery,history:()=>`<h1>${t('سجل الطلب','Application history')}</h1>${panel(ltr('RF-2026-'+current.record.id),applicationHistory(current.record,current.actor==='R'))}`};const staff=current.actor==='R';$('#root').innerHTML=guide()+header()+`<div class="workspace ${staff?'':'applicant'}">${staff?`<aside class="side"><nav aria-label="${t('تنقل الموظف','Staff navigation')}">${btn(t('قائمة الطلبات','Application queue'),'queue',current.spec.screen==='queue'?'aria-current="page"':'')}${jump(t('المستندات والفحوص','Documents and checks'),'review',0)}${jump(t('القرار والتعارض','Decision and conflict'),'decision',0)}</nav><p class="small muted stickyhint">${t('إجراءات وبيانات افتراضية.','Fictional data and procedures.')}</p></aside>`:''}<main class="main" id="main" tabindex="-1"><p class="route" aria-label="${t('المسار المقترح','Proposed route')}">${esc(current.route)}</p>${screens[current.spec.screen]?.()||unavailable()}</main></div>${inspector()}`;if(focus){const el=$('#validation-summary')||$('#scene-heading');el?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function loadScene(c,i,push=true){chapter=chapters.some(x=>x.key===c)||c==='tour'?c:'tour';index=Math.min(Math.max(Number(i)||0,0),sceneCount()-1);current=snapshot(chapter,index);buffers={};queue={q:current.spec.query||'',status:current.spec.filter||'all',product:'all',assignment:'all',sort:'date-desc',page:1};if(push)historyURL();render(true);}
function historyURL(replace=false){const hash=`#/walk/${chapter}/${index+1}?lang=${lang}`;if(replace)window.history.replaceState(null,'',hash);else window.history.pushState(null,'',hash);}
function fromURL(){const m=location.hash.match(/^#\/walk\/([a-z]+)\/(\d+)(?:\?(.*))?$/);lang=m?new URLSearchParams(m[3]||'').get('lang')==='en'?'en':'ar':'ar';loadScene(m?.[1]||'tour',m?Number(m[2])-1:0,false);}
function changeView(screen,r=current.record,actor=current.actor){current={...current,record:clone(r),actor,spec:{screen,id:r.id,actor,label:['استكشاف الشاشة','Explore screen'],note:['معاينة مستقلة باستخدام بيانات العينة. استخدم تبويبات الدليل للعودة إلى السيناريو الكامل.','Independent preview using seed data. Use walkthrough chapters to return to the complete scenario.']}};current.route=routeFor(current.spec,r);buffers={};render();$('#main').focus();window.scrollTo({top:0,behavior:'instant'});}
function modal(title,body){opener=document.activeElement;const d=$('#dialog');d.innerHTML=`<div class="dialogtop"><h2 id="dialog-title">${title}</h2>${btn(t('إغلاق','Close'),'close','autofocus')}</div>${body}`;d.showModal();d.querySelector('[autofocus]').focus();}
function closeModal(){const d=$('#dialog');d.close();if(opener?.isConnected)opener.focus();}
function toast(ar,en){const d=$('#live');d.hidden=false;d.textContent=t(ar,en);clearTimeout(toast.timer);toast.timer=setTimeout(()=>d.hidden=true,5500);}
function preview(slot){const r=current.record,x=current.spec,label=[...docLabels,r.product==='equipment'?['عرض سعر المعدات','Supplier quotation']:['خطة شراء المخزون','Stock purchase plan']][slot];const unreadable=(r.id==='1004'&&slot===3||r.id==='1012'&&slot===2||r.id==='1013'&&slot===3)&&!x.response&&!['ready','saved'].includes(x.file);const body=unreadable?notice(t('مثال أصل غير مقروء. وجود ملف لا يثبت ملاءمة المحتوى.','Unreadable original example. File presence does not prove content suitability.'),'warning'):slot===0?`<dl>${def(t('الاسم كما أُدخل','Name as entered'),entered(r.name))}${def(t('المدينة','City'),entered(r.city))}</dl>`:slot===1?`<dl>${def(t('النشاط','Business'),entered(r.business))}${def(t('العنوان','Address'),entered(r.address))}${def(t('بدأ في','Operating since'),ltr(r.since))}</dl>`:slot===2?`<p>${r.id==='1005'?t('أبريل، مايو، يونيو2026','April, May, June 2026'):t('يوليو، أغسطس، سبتمبر2026','July, August, September 2026')}</p>${r.id==='1006'?`<p>${t('يوليو صفر. أغسطس وسبتمبر: الإيرادات900,000 والمصروفات600,000 لكل شهر.','July is zero. August and September each have 900,000 revenue and 600,000 expenses.')}</p>`:''}<dl>${def(t('متوسط الإيرادات','Average revenue'),money(r.revenue))}${def(t('متوسط المصروفات','Average expenses'),money(r.expenses))}</dl>`:`<p>${entered(r.explanation||inventoryText)}</p><dl>${def(t('التكلفة الإجمالية','Total cost'),money(r.budget))}</dl>`;modal(txt(label),`<article class="paper"><span class="stamp">DEMO / تجريبي</span><h3>${txt(label)}</h3><p>${entered(r.name)} · ${entered(r.business)}</p>${body}<p class="small stickyhint">${t('رسم محتوى مستند تجريبي؛ لا توجد بايتات ملف فعلية في هذا النموذج.','Illustrated sample document content; this prototype contains no actual attachment bytes.')}</p></article>`);}
function leavePrompt(){const textOnly=['request','decision'].includes(current.spec.screen);modal(t('لديك عمل غير محفوظ','You have unfinished work'),`<p>${textOnly?t('لا يُرسل طلب التصحيح أو القرار عند المغادرة.','Leaving never sends the correction request or decision.'):t('يمكن حفظ التقدم دون إرسال الطلب. فشل الحفظ يبقيك في نفس الشاشة.','Save progress without submitting. A failed save keeps you on this screen.')}</p>${notice(t('يجب انتظار تجهيز الملفات الجاري، ومعالجة الاختيارات الفاشلة أو استبعادها، قبل الحفظ والمغادرة.','Wait for active file preparation and resolve or discard failed selections before Save and leave.'))}<div class="sampleactions">${!textOnly?btn(t('معاينة حفظ ومغادرة','Preview Save and leave'),'leave-save','','primary'):''}${btn(t('تجاهل التغييرات والمغادرة','Discard changes and leave'),'leave-discard')}${btn(t('البقاء هنا','Stay here'),'close')}</div>`);}
function controls(){modal(t('أدوات العرض المقترحة','Proposed demo controls'),`<p>${t('هذه قائمة تصميم. الإخفاقات مؤقتة في التبويب؛ افتراضياً لا إخفاقات عشوائية.','This is a design inventory. Failures are tab-local; no random failures by default.')}</p><dl>${def(t('بطء الطلبات','Slow requests'),ltr('400 → 1,500 ms'))}${def(t('بطء التجهيز','Slow preparation'),ltr('1,200 → 4,000 ms'))}</dl><div class="stack" style="margin-top:16px">${jump(t('فشل حفظ التقدم التالي','Fail next progress save'),'files',5)}${jump(t('فشل الإرسال التالي','Fail next submission'),'files',9)}${jump(t('فشل الرفع التالي','Fail next upload'),'files',3)}${jump(t('فشل كتابة التخزين التالية','Fail next storage write'),'recovery',11)}${jump(t('إنهاء الجلسة','Expire session'),'recovery',4)}${jump(t('مثال وصول ممنوع','Forbidden example'),'recovery',6)}${jump(t('محاكاة نقل الإسناد','Simulate colleague reassignment'),'decision',1)}${jump(t('إعادة الضبط','Reset demo'),'recovery',10)}</div><p class="small stickyhint">${t('يتسلح فشل موجه واحد فقط، ويُستهلك بعد اجتياز التحقق والوصول والنسخ في محاولة مؤهلة. الإعادة الصريحة التالية عادية.','Only one targeted failure is armed. Consume it on an eligible attempt after validation, access and version checks. The next explicit retry runs normally.')}</p>`);}
function routeDialog(){modal(t('خريطة المسارات المقترحة','Proposed route map'),`<p>${t('روابط هذا النموذج تحمل مشاهد الدليل. المسارات أدناه هي المقترح للتطبيق الفعلي.','Prototype links address walkthrough scenes. These paths are proposed for the actual application.')}</p><dl>${[
['/products',t('المقارنة العامة','Public comparison')],['/sign-in',t('اختيار الهوية واستئناف الرابط المسموح','Identity chooser and permitted deep-link resumption')],['/applications',t('طلبات المتقدم','Applicant list')],['/applications/new?product=inventory',t('بدء مسودة جديدة','Start a new draft')],['/applications/:id/edit?step=personal',t('خطوات المسودة','Draft steps')],['/applications/:id',t('الحالة والتفاصيل','Status and detail')],['/applications/:id/corrections/current',t('مساحة الرد الخاصة','Private correction workspace')],['/applications/:id/history',t('السجل العام','Public history')],['/notifications',t('تنبيهات المتقدم','Applicant notifications')],['/staff/applications',t('القائمة مع البحث والفلاتر والفرز والصفحة','Queue with search, filters, sort and page')],['/staff/applications/:id',t('المراجعة ومقاطعها','Review and section anchors')],['/staff/applications/:id/correction-request',t('تجهيز طلب تصحيح','Compose correction request')],['/staff/applications/:id/decision',t('تجهيز قرار وتأكيد جديد','Compose decision and confirm afresh')],['/applications/:id/repayment',t('جدول المتقدم للموافق عليه فقط','Applicant illustration, approved only')],['/staff/applications/:id/repayment',t('جدول الموظف للموافق عليه فقط','Staff illustration, approved only')],['/applications/:id/print',t('ملخص المتقدم','Applicant summary')],['/staff/applications/:id/print',t('نفس معلومات ملخص المتقدم','Same applicant-visible summary')],['/components',t('معرض عام','Public gallery')],['/demo/reset',t('إعادة ضبط عامة بتأكيد','Public reset with confirmation')]
].map(([p,n])=>def(ltr(p),n)).join('')}</dl><p class="small">${t('لا قيم حقول ولا أسباب ولا ملفات في الرابط. تُفحص الهوية والحالة عند كل رابط عميق.','No field values, reasons or files in URLs. Every deep link rechecks identity and current state.')}</p>`);}
document.addEventListener('click',e=>{
 const anchor=e.target.closest('[data-focus]');if(anchor){e.preventDefault();$('#'+anchor.dataset.focus)?.focus();$('#'+anchor.dataset.focus)?.scrollIntoView({block:'center',behavior:'instant'});return;}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='close')return closeModal();
 if(['jump','chapter','next','previous','restart'].includes(a)){if($('#dialog').open)closeModal();return loadScene(a==='jump'||a==='chapter'?b.dataset.chapter:chapter,a==='jump'?Number(b.dataset.index):a==='chapter'||a==='restart'?0:a==='next'?index+1:index-1);}
 if(a==='language'){const focus=document.activeElement?.dataset?.field;lang=lang==='ar'?'en':'ar';historyURL(true);render();(focus?$('#f-'+focus):$('[data-action="language"]'))?.focus();return;}
 if(a==='preview')return preview(Number(b.dataset.slot));
 if(a==='preview-error')return modal(t('تعذر عرض المعاينة','Preview could not render'),notice(t('الملف محفوظ ولم يُحذف. الخيارات المقترحة: إعادة المعاينة، فتح الملف أو تنزيله بعد فحص الوصول.','The saved file remains intact. Proposed recovery: retry preview, open or download after access checks.'),'error')+btn(t('معاينة إعادة المحاولة','Preview retry'),'preview','data-slot="3"'));
 if(a==='form-step'){current.spec.step=b.dataset.step;current.route=routeFor(current.spec,current.record);render();$('#main').focus();return;}
 if(a==='product')return modal(t('تغيير منتج المسودة','Change draft product'),notice(t('سيُزال مستند خطة شراء المخزون عند نجاح الحفظ التالي أو الإرسال. تبقى الحقول المشتركة وثلاثة مستندات. المبلغ والمدة لن يتغيرا تلقائياً.','The stock plan is removed on the next successful save or submission. Keep common input and three shared files. Amount and term do not change automatically.'),'warning')+`<div class="sampleactions">${jump(t('معاينة تأكيد التغيير','Preview confirmed change'),'apply',8,'primary')}${btn(t('إلغاء','Cancel'),'close')}</div>`);
 if(a==='leave')return leavePrompt();
 if(a==='leave-save')return modal(t('حفظ ثم مغادرة','Save, then leave'),`<p>${t('يمثل هذا المشهد الحفظ الناجح. لا يتم انتقال فعلي أو حفظ دائم في النموذج. الفشل يبقيك في مكانك مع المدخلات.','This scene illustrates a successful save. This prototype performs no durable save. Failure keeps you here with your input.')}</p><div class="sampleactions">${btn(t('معاينة نجاح الحفظ','Preview successful save'),'leave-discard','','primary')}${jump(t('معاينة فشل الحفظ','Preview failed save'),'files',5)}</div>`);
 if(a==='leave-discard'){closeModal();buffers={};return changeView(current.actor==='R'?'queue':'list',current.record,current.actor||'A');}
 if(a==='switch'){if(Object.keys(buffers).length||current.spec.dirty)return leavePrompt();return modal(t('تبديل الهوية التجريبية','Switch demo identity'),`<p>${t('ينقلك التبديل إلى صفحة الهوية الرئيسية بعد معالجة العمل غير المحفوظ.','Switching opens the new identity’s home after resolving unfinished work.')}</p><div class="sampleactions">${['A','B','C','R'].map(k=>btn(txt(names[k]),'identity',`data-actor="${k}"`)).join('')}</div>`);}
 if(a==='identity'){if($('#dialog').open)closeModal();const actor=b.dataset.actor;if(current.spec.screen==='expired'&&actor==='A')return loadScene('recovery',5);if(current.spec.screen==='expired'&&actor!=='A')return modal(t('تجاهل الإدخال السابق؟','Discard previous input?'),`<p>${t('يجب تجاهل عمل الهوية السابقة قبل اختيار هوية مختلفة.','Discard the previous identity’s unfinished work before choosing another identity.')}</p>${btn(t('تجاهل واستخدم الهوية المختارة','Discard and use selected identity'),'identity-confirm',`data-actor="${actor}"`)}${btn(t('البقاء','Stay'),'close')}`);return changeView(actor==='R'?'queue':'list',seeds.find(r=>actor==='R'||r.owner===actor),actor);}
 if(a==='identity-confirm'){closeModal();return changeView(b.dataset.actor==='R'?'queue':'list',seeds.find(r=>b.dataset.actor==='R'||r.owner===b.dataset.actor),b.dataset.actor);}
 if(a==='home')return changeView(current.actor==='R'?'queue':'list',current.record,current.actor||'A');
 if(a==='record'){const r=seeds.find(r=>r.id===b.dataset.id);if(!r||current.actor!=='R'&&r.owner!==current.actor||current.actor==='R'&&r.status==='draft')return changeView('unavailable');return changeView(current.actor==='R'?'review':r.status==='draft'?'form':'detail',r);}
 if(a==='open-correction')return changeView('correction');
 if(a==='queue'){if(Object.keys(buffers).length)return leavePrompt();return changeView('queue',current.record,'R');}
 if(a==='repayment')return changeView('repayment');
 if(a==='print-view')return changeView('print');
 if(a==='back-record')return changeView(current.actor==='R'?'review':'detail');
 if(a==='print')return window.print();
 if(a==='mark-read'){$('#read-'+b.dataset.id).textContent=t('مقروء','Read');return toast('تغيّرت حالة القراءة في هذا المشهد فقط.','Read state changed in this scene only.');}
 if(a==='page'){queue.page=Number(b.dataset.page);$('#queue-results').innerHTML=queueResults();$('#result-count')?.setAttribute('tabindex','-1');$('#result-count')?.focus();return;}
 if(a==='clear-search'||a==='clear-filters'){if(a==='clear-search')queue.q='';else{queue.status='all';queue.product='all';queue.assignment='all';}queue.page=1;return render();}
 if(a==='assignment')return modal(t('إدارة الإسناد','Manage assignment'),`<p>${t('تأكيد النقل يسمي المراجع الحالي والجديد، ويحافظ على جميع نتائج المراجعة. إزالة الإسناد متاحة في مُرسل فقط.','Transfer confirmation names the current and next reviewer and preserves review results. Unassign is available only while Submitted.')}</p><dl>${def(t('المراجع الحالي','Current reviewer'),assignee(current.record))}${def(t('المراجع المقترح','Proposed reviewer'),current.record.assignee==='R'?txt(names.K):txt(names.R))}</dl><div class="sampleactions">${jump(t('معاينة النتيجة','Preview outcome'),'queue',7,'primary')}${btn(t('إلغاء','Cancel'),'close')}</div>`);
 if(a==='note-policy')return modal(t('حفظ الملاحظة الداخلية','Saving an internal note'),`<p>${t('حفظ مستقل للمراجع المسند في الحالات المسموحة. لا يظهر النص للمتقدم. إذا تعارضت النسخة يبقى النص غير مطبق حتى فحص الأحدث.','An explicit save by the assigned reviewer in permitted states. The applicant cannot see the text. On version conflict, retain it as unapplied work until latest information is inspected.')}</p>`);
 if(a==='decision-confirm'||a==='request-confirm')return modal(a==='decision-confirm'?t('تأكيد القرار النهائي','Confirm final decision'):t('تأكيد طلب التصحيحات','Confirm correction request'),`<p>${ltr('RF-2026-'+current.record.id)} · ${entered(current.record.name)}</p><p>${a==='decision-confirm'?t('أكد القرار والسبب بعد فحص النسخة الحالية. لا يمكن فتح القرار النهائي مجدداً.','Confirm decision and reason after inspecting the current record. Final decisions cannot be reopened.'):t('راجع الأهداف والأسباب. سيرى المتقدم هذا الطلب بعد تأكيده.','Review targets and reasons. The applicant sees the request after confirmation.')}</p><p class="notearea">${esc(buffers.decisionReason||buffers['reason-0']||t('السبب المعروض في الشاشة السابقة.','The reason shown on the preceding screen.'))}</p><div class="sampleactions">${btn(t('العودة للمراجعة','Return to inspect'),'close')}${primaryNext()}</div>`);
 if(a==='file-rules')return modal(t('عينات قبول الملفات ورفضها','File acceptance and rejection examples'),`<ul>${[
['PDF/JPEG/PNG، أكبر من0 وحتى5,000,000 بايت، وMIME متوافق.','PDF/JPEG/PNG, greater than 0 and at most 5,000,000 bytes, with matching MIME.'],
['امتداد غير مسموح، ملف فارغ، حجم زائد أوMIME غير متوافق: رفض قبل الرفع.','Unsupported extension, empty file, oversized file or mismatched MIME: reject before preparation.'],
['MIME فارغ يُستنتج من امتداد مسموح. محتوى غير مقروء قد يجتاز الرفع ثم يحتاج تصحيحاً في المراجعة.','Empty MIME derives from an allowed extension. Unreadable content can pass preparation and later need review correction.'],
['بديل مطابق المحتوى لا يحقق هدف الاستبدال. يحدد المحتوى، وليس الاسم أو الوقت، اختلاف الملف.','Identical content does not fulfill replacement. File content, not its name or timestamp, determines a change.']].map(a=>`<li>${txt(a)}</li>`).join('')}</ul>`);
 if(a==='controls')return controls();
 if(a==='routes')return routeDialog();
 if(a==='retry-startup')return loadScene('recovery',7);
 if(a==='reset-confirm'){if($('#reset-check').checked){lang='ar';return loadScene('recovery',12);}}
 if(a==='sample')return toast('زر تجريبي لفحص التركيز.','Sample button for focus inspection.');
});
document.addEventListener('input',e=>{if(e.target.dataset.field){buffers[e.target.dataset.field]=e.target.value;return;}if(e.target.id==='queue-search'){queue.q=e.target.value;queue.page=1;$('#queue-results').innerHTML=queueResults();}});
document.addEventListener('change',e=>{if(e.target.id==='scene-select')return loadScene(chapter,Number(e.target.value));if(e.target.dataset.filter){queue[e.target.dataset.filter]=e.target.value;queue.page=1;$('#queue-results').innerHTML=queueResults();}if(e.target.id==='reset-check')$('[data-action="reset-confirm"]').disabled=!e.target.checked;});
window.addEventListener('popstate',fromURL);
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
fromURL();
